import{_ as d,o as e,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"数据结构与算法全景","description":"","frontmatter":{"title":"数据结构与算法全景","outline":[2,3]},"headers":[],"relativePath":"frontend/topics/algorithms/index.md","filePath":"frontend/topics/algorithms/index.md","lastUpdated":1785589115000}'),o={name:"frontend/topics/algorithms/index.md"};function l(i,t,h,n,c,s){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="数据结构与算法全景" tabindex="-1">数据结构与算法全景 <a class="header-anchor" href="#数据结构与算法全景" aria-label="Permalink to &quot;数据结构与算法全景&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>数据结构回答“数据怎样组织”，算法回答“怎样在有限时间和空间内得到结果”。前端开发不需要把工作变成竞赛题训练，但需要能识别数据的形状、操作频率和规模上限，再选择数组、索引、队列、树或图等合适模型。</p><p>本分组以 TypeScript 实现通用算法，关注浏览器和 Node.js 都能复用的能力。它不会按题号罗列解法，也不会把某一种写法包装成所有场景的最优解；每篇都把不变量、复杂度、完整实现、验证方法和适用边界连在一起。</p><h2 id="_1-知识地图" tabindex="-1">1. 知识地图 <a class="header-anchor" href="#_1-知识地图" aria-label="Permalink to &quot;1. 知识地图&quot;">​</a></h2><h3 id="_1-1-三个层次" tabindex="-1">1.1 三个层次 <a class="header-anchor" href="#_1-1-三个层次" aria-label="Permalink to &quot;1.1 三个层次&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层次</th><th>核心问题</th><th>代表内容</th></tr></thead><tbody><tr><td>数据表示</td><td>数据是什么形状，怎样读取和更新</td><td>数组、Map、Set、树、图、堆</td></tr><tr><td>求解策略</td><td>每一步怎样缩小问题或维护状态</td><td>双指针、滑动窗口、二分、遍历、回溯、动态规划</td></tr><tr><td>工程约束</td><td>规模、延迟、内存和正确性如何验证</td><td>复杂度、边界用例、基准测试、不可变更新</td></tr></tbody></table><p>一个问题通常会同时跨越三个层次。例如，依赖构建顺序以有向图表示，用拓扑排序求解，再用节点数 <code>V</code> 和边数 <code>E</code> 分析为 <code>O(V + E)</code>。</p><h3 id="_1-2-基本判断链路" tabindex="-1">1.2 基本判断链路 <a class="header-anchor" href="#_1-2-基本判断链路" aria-label="Permalink to &quot;1.2 基本判断链路&quot;">​</a></h3><p>拿到数据处理需求时，依次回答：</p><ol><li>输入是序列、集合、层级还是关系网络；</li><li>最频繁的是查询、插入、删除、排序还是范围计算；</li><li>输入规模和操作次数的上限是多少；</li><li>是否需要保持原顺序、稳定性或不可变引用；</li><li>最坏情况能否接受，是否允许用额外空间换时间；</li><li>怎样构造边界输入并验证结果。</li></ol><p>这条链路比先背某个算法名称更可靠。</p><h2 id="_2-文章索引" tabindex="-1">2. 文章索引 <a class="header-anchor" href="#_2-文章索引" aria-label="Permalink to &quot;2. 文章索引&quot;">​</a></h2><h3 id="_2-1-基础模型" tabindex="-1">2.1 基础模型 <a class="header-anchor" href="#_2-1-基础模型" aria-label="Permalink to &quot;2.1 基础模型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文章</th><th>解决的问题</th><th>学习重点</th></tr></thead><tbody><tr><td><a href="/frontend/topics/algorithms/data-structures-complexity">数据结构与复杂度</a></td><td>怎样估算成本并选择内置结构</td><td>时间、空间、摊还分析，Array、Map、Set</td></tr><tr><td><a href="/frontend/topics/algorithms/sequences">数组、字符串、双指针与滑动窗口</a></td><td>怎样处理连续、有序的数据</td><td>序列边界、Unicode、窗口不变量</td></tr><tr><td><a href="/frontend/topics/algorithms/hashing-caches">哈希、索引、去重与缓存结构</a></td><td>怎样加速重复查询并维护唯一性</td><td>键模型、索引、多重映射、TTL、LRU</td></tr><tr><td><a href="/frontend/topics/algorithms/stacks-queues-heaps">栈、队列、双端队列与优先队列</a></td><td>怎样按顺序、两端或优先级取出元素</td><td>LIFO、FIFO、环形缓冲区、二叉堆</td></tr></tbody></table><h3 id="_2-2-层级与关系" tabindex="-1">2.2 层级与关系 <a class="header-anchor" href="#_2-2-层级与关系" aria-label="Permalink to &quot;2.2 层级与关系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文章</th><th>解决的问题</th><th>学习重点</th></tr></thead><tbody><tr><td><a href="/frontend/topics/algorithms/trees-tries">树、Trie、DOM 与 AST 遍历</a></td><td>怎样处理父子层级与前缀</td><td>DFS、BFS、前序/后序、Trie、TreeWalker</td></tr><tr><td><a href="/frontend/topics/algorithms/graphs-topological">图、依赖关系与拓扑排序</a></td><td>怎样处理多对多关系和依赖顺序</td><td>邻接表、可达性、最短步数、DAG、环检测</td></tr></tbody></table><h3 id="_2-3-求解策略" tabindex="-1">2.3 求解策略 <a class="header-anchor" href="#_2-3-求解策略" aria-label="Permalink to &quot;2.3 求解策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文章</th><th>解决的问题</th><th>学习重点</th></tr></thead><tbody><tr><td><a href="/frontend/topics/algorithms/search-sort-selection">排序、二分查找、区间与 Top K</a></td><td>怎样建立顺序并快速定位或筛选</td><td>比较器、边界二分、区间合并、堆选择</td></tr><tr><td><a href="/frontend/topics/algorithms/recursion-dp">递归、分治、回溯与动态规划</a></td><td>怎样拆分问题、枚举选择并复用子结果</td><td>递归不变量、搜索树、状态与转移</td></tr><tr><td><a href="/frontend/topics/algorithms/frontend-practice">前端典型算法实现</a></td><td>怎样把基础结构组合到真实前端场景</td><td>树形筛选、变高虚拟列表、并发调度</td></tr></tbody></table><h2 id="_3-结构选择速查" tabindex="-1">3. 结构选择速查 <a class="header-anchor" href="#_3-结构选择速查" aria-label="Permalink to &quot;3. 结构选择速查&quot;">​</a></h2><h3 id="_3-1-按数据形状选择" tabindex="-1">3.1 按数据形状选择 <a class="header-anchor" href="#_3-1-按数据形状选择" aria-label="Permalink to &quot;3.1 按数据形状选择&quot;">​</a></h3><table tabindex="0"><thead><tr><th>数据形状或操作</th><th>首选模型</th><th>需要警惕</th></tr></thead><tbody><tr><td>有序、允许重复、按位置访问</td><td>Array</td><td>头部删除和中间插入通常为 <code>O(n)</code></td></tr><tr><td>动态键值和大量按键查询</td><td>Map</td><td>键相等规则、索引同步、序列化</td></tr><tr><td>唯一值和成员判断</td><td>Set</td><td>对象按身份而非内容去重</td></tr><tr><td>后进先出的嵌套状态</td><td>Stack</td><td>递归深度与栈溢出</td></tr><tr><td>先进先出的任务</td><td>Queue</td><td>避免大规模反复 <code>shift()</code></td></tr><tr><td>随时取最小或最大项</td><td>Heap / PriorityQueue</td><td>只保证堆顶，不保证整体有序</td></tr><tr><td>严格父子层级</td><td>Tree</td><td>深树的递归深度</td></tr><tr><td>前缀查询</td><td>Trie</td><td>内存开销可能高于排序数组</td></tr><tr><td>多对多关系或依赖</td><td>Graph</td><td>重复访问和环</td></tr></tbody></table><h3 id="_3-2-按问题信号选择策略" tabindex="-1">3.2 按问题信号选择策略 <a class="header-anchor" href="#_3-2-按问题信号选择策略" aria-label="Permalink to &quot;3.2 按问题信号选择策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>问题信号</th><th>常用策略</th><th>关键不变量</th></tr></thead><tbody><tr><td>已排序序列中定位边界</td><td>二分查找</td><td>答案始终位于搜索区间</td></tr><tr><td>连续区间且窗口可增减</td><td>滑动窗口</td><td>窗口内始终满足或逼近约束</td></tr><tr><td>两端相向或同向扫描</td><td>双指针</td><td>已排除区域无需再次检查</td></tr><tr><td>父结果由独立子问题组合</td><td>分治</td><td>子问题覆盖完整且不重叠或可合并</td></tr><tr><td>需要列举合法选择</td><td>回溯</td><td>路径状态在进入和退出时对称恢复</td></tr><tr><td>子问题重复且有最优子结构</td><td>动态规划</td><td>状态定义足以决定后续结果</td></tr><tr><td>依赖必须先于使用者</td><td>拓扑排序</td><td>只有入度为零的节点可执行</td></tr></tbody></table><p>策略不是由关键词自动决定的。若窗口缩小时无法恢复约束，滑动窗口就未必成立；若子问题几乎不重复，动态规划的缓存可能只有成本没有收益。</p><h2 id="_4-复杂度速查" tabindex="-1">4. 复杂度速查 <a class="header-anchor" href="#_4-复杂度速查" aria-label="Permalink to &quot;4. 复杂度速查&quot;">​</a></h2><h3 id="_4-1-常见增长量级" tabindex="-1">4.1 常见增长量级 <a class="header-anchor" href="#_4-1-常见增长量级" aria-label="Permalink to &quot;4.1 常见增长量级&quot;">​</a></h3><table tabindex="0"><thead><tr><th>复杂度</th><th><code>n</code> 增大时的含义</th><th>常见场景</th></tr></thead><tbody><tr><td><code>O(1)</code></td><td>与输入规模无关的固定次数操作</td><td>按索引读取、读取堆顶</td></tr><tr><td><code>O(log n)</code></td><td>每一步排除固定比例</td><td>二分查找、堆上浮或下沉</td></tr><tr><td><code>O(n)</code></td><td>最坏检查全部输入一次</td><td>遍历、哈希索引构建</td></tr><tr><td><code>O(n log n)</code></td><td>线性层数乘对数层级</td><td>比较排序、堆排序</td></tr><tr><td><code>O(n²)</code></td><td>每项又处理与输入同阶的数据</td><td>朴素两两比较</td></tr><tr><td><code>O(2^n)</code> / <code>O(n!)</code></td><td>选择组合急剧增长</td><td>子集、排列的完整枚举</td></tr></tbody></table><h3 id="_4-2-复杂度不是耗时承诺" tabindex="-1">4.2 复杂度不是耗时承诺 <a class="header-anchor" href="#_4-2-复杂度不是耗时承诺" aria-label="Permalink to &quot;4.2 复杂度不是耗时承诺&quot;">​</a></h3><p>大 O 描述输入增长趋势，不包含常数、引擎优化、垃圾回收和设备差异。<code>O(n)</code> 方案在很小数据上可能不如简单的 <code>O(n²)</code> 写法；<code>Map</code> 的平均次线性访问也不是 ECMAScript 对每次操作严格 <code>O(1)</code> 的承诺。</p><p>工程决策需要同时记录：</p><ul><li><code>n</code>、<code>V</code>、<code>E</code> 等符号各自代表什么；</li><li>分析的是最坏、平均还是摊还成本；</li><li>是否包含输出本身占用的空间；</li><li>实际数据规模、调用频率和关键延迟分位。</li></ul><h2 id="_5-推荐学习顺序" tabindex="-1">5. 推荐学习顺序 <a class="header-anchor" href="#_5-推荐学习顺序" aria-label="Permalink to &quot;5. 推荐学习顺序&quot;">​</a></h2><h3 id="_5-1-日常前端路线" tabindex="-1">5.1 日常前端路线 <a class="header-anchor" href="#_5-1-日常前端路线" aria-label="Permalink to &quot;5.1 日常前端路线&quot;">​</a></h3><p>按以下顺序学习即可覆盖大多数业务和工程问题：</p><ol><li>数据结构与复杂度；</li><li>序列与哈希；</li><li>栈、队列与优先队列；</li><li>树与图；</li><li>排序、搜索与区间；</li><li>递归、回溯与动态规划；</li><li>前端典型算法实现。</li></ol><h3 id="_5-2-专项路线" tabindex="-1">5.2 专项路线 <a class="header-anchor" href="#_5-2-专项路线" aria-label="Permalink to &quot;5.2 专项路线&quot;">​</a></h3><ul><li>组件树、菜单、DOM、AST：优先学习树遍历，再学习图和递归；</li><li>构建工具、包依赖、任务编排：优先学习图、拓扑排序和优先队列；</li><li>搜索建议、数据表格、虚拟列表：优先学习序列、索引、二分和 Trie；</li><li>缓存与资源调度：优先学习 Map、双向顺序模型、堆和队列。</li></ul><h2 id="_6-学习与验证方法" tabindex="-1">6. 学习与验证方法 <a class="header-anchor" href="#_6-学习与验证方法" aria-label="Permalink to &quot;6. 学习与验证方法&quot;">​</a></h2><h3 id="_6-1-每个实现都要说明不变量" tabindex="-1">6.1 每个实现都要说明不变量 <a class="header-anchor" href="#_6-1-每个实现都要说明不变量" aria-label="Permalink to &quot;6.1 每个实现都要说明不变量&quot;">​</a></h3><p>不变量是在循环或递归每一步之后仍然成立的条件。例如二分查找中“答案仍在 <code>[left, right)</code>”，拓扑排序中“入度为零的节点不再依赖未处理节点”。先写清不变量，代码才不容易退化成边界猜测。</p><h3 id="_6-2-至少覆盖四类测试" tabindex="-1">6.2 至少覆盖四类测试 <a class="header-anchor" href="#_6-2-至少覆盖四类测试" aria-label="Permalink to &quot;6.2 至少覆盖四类测试&quot;">​</a></h3><ol><li>最小输入：空集合、单元素；</li><li>典型输入：题意中的正常数据；</li><li>边界输入：重复值、负数、Unicode、断开的图；</li><li>失败输入：环、非法索引、无法满足的约束。</li></ol><p>性能敏感实现还应增加规模测试，但基准结果必须在目标运行时和真实数据分布上测量。</p><h3 id="_6-3-验收问题" tabindex="-1">6.3 验收问题 <a class="header-anchor" href="#_6-3-验收问题" aria-label="Permalink to &quot;6.3 验收问题&quot;">​</a></h3><ul><li>能否用一句话说明数据结构维护的关系；</li><li>能否写出关键不变量，而不只背代码；</li><li>能否给出时间和额外空间复杂度；</li><li>能否说明输入是否被修改；</li><li>能否构造一个会击穿错误实现的边界用例；</li><li>能否判断简单方案何时比复杂结构更合适。</li></ul><h2 id="_7-参考资料" tabindex="-1">7. 参考资料 <a class="header-anchor" href="#_7-参考资料" aria-label="Permalink to &quot;7. 参考资料&quot;">​</a></h2><ul><li><a href="https://tc39.es/ecma262/multipage/indexed-collections.html" target="_blank" rel="noreferrer">ECMAScript：Indexed Collections</a></li><li><a href="https://tc39.es/ecma262/multipage/keyed-collections.html" target="_blank" rel="noreferrer">ECMAScript：Keyed Collections</a></li><li><a href="https://dom.spec.whatwg.org/" target="_blank" rel="noreferrer">WHATWG DOM Standard</a></li><li><a href="https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-fall-2011/" target="_blank" rel="noreferrer">MIT OpenCourseWare：Introduction to Algorithms</a></li><li><a href="https://algs4.cs.princeton.edu/home/" target="_blank" rel="noreferrer">Princeton Algorithms, 4th Edition</a></li></ul>',48)])])}const u=d(o,[["render",l]]);export{p as __pageData,u as default};
